      "id": "REG.DTP.FIXED_INCOME",
      "label": "Contractual fixed regular gross income for the DTP test",
      "label_id": "Penghasilan bruto tetap dan teratur berdasarkan kontrak untuk uji DTP",
      "valid_from": "2026-01-01",
      "valid_until": "2026-12-31",
      "recorded_on": "2025-12-31",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
          "value": "period"
        },
        {
          "name": "produces",
          "value": "dtp_fixed_income"
        },
        {
          "name": "expression",
          "value": "round(base_salary + fixed_allowance + hr('dtp_other_fixed_regular_income'), 1, 'down')"
