        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
          "value": "period"
        },
        {
          "name": "produces",
          "value": "pph21_dtp"
        },
        {
          "name": "expression",
          "value": "pph21_due if dtp_facility else 0"
        },
        {
          "name": "condition",
          "value": "not is_final_period"
        }
      ],
      "source": [
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 2 ayat (2) dan ayat (3)",
          "page": 4,
          "quote": "Pajak Penghasilan Pasal 21 sebagaimana dimaksud pada\nayat (1) atas seluruh penghasilan bruto dalam tahun 2026\nyang diterima atau diperoleh Pegawai tertentu dari\nPemberi Kerja dengan kriteria tertentu diberikan insentif\nPajak Penghasilan Pasal 21 ditanggung pemerintah.\n(3) Jangka waktu pemberian insentif Pajak Penghasilan\nPasal 21 ditanggung pemerintah sebagaimana dimaksud\npada ayat (2) diberikan untuk Masa Pajak Januari 2026\nsampai dengan Masa Pajak Desember 2026."
        }
      ]
    },
    {
      "kind": "rule",
      "id": "REG.DTP.FINAL",
      "label": "Nonnegative final-period DTP cash entitlement",
      "label_id": "Hak pembayaran tunai DTP masa pajak terakhir yang tidak negatif",
