      "valid_until": "2026-12-31",
      "recorded_on": "2025-12-31",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
          "value": "period"
        },
        {
          "name": "produces",
          "value": "pph21_dtp"
        },
        {
          "name": "expression",
          "value": "max(0, final_period_tax) if dtp_facility else 0"
        },
        {
          "name": "condition",
          "value": "is_final_period"
        }
      ],
      "source": [
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 5 ayat (5) dan ayat (6)",
          "page": 6,
          "quote": "Dalam hal jumlah Pajak Penghasilan Pasal 21 ditanggung\npemerintah untuk Pegawai Tetap tertentu yang telah\ndipotong dan diberikan insentif dalam tahun kalender\nyang bersangkutan lebih besar dari Pajak Penghasilan\nPasal 21 yang terutang untuk 1 (satu) Tahun Pajak,\nkelebihan Pajak Penghasilan Pasal 21 ditanggung\npemerintah tidak dikembalikan kepada Pegawai Tetap\nbersangkutan.\n(6) Dalam hal Pemberi Kerja dengan kriteria tertentu yang\nmemanfaatkan insentif Pajak Penghasilan Pasal 21\nditanggung pemerintah menyampaikan Surat\nPemberitahuan Masa Pajak Penghasilan Pasal 21/26 dan\nmenyatakan kelebihan pembayaran, kelebihan\npembayaran yang berasal dari Pajak Penghasilan Pasal 21\nditanggung pemerintah tidak dapat dikembalikan dan\ntidak dapat dikompensasikan."
        },
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 2 ayat (3)",
          "page": 4,
          "quote": "Jangka waktu pemberian insentif Pajak Penghasilan\nPasal 21 ditanggung pemerintah sebagaimana dimaksud\npada ayat (2) diberikan untuk Masa Pajak Januari 2026\nsampai dengan Masa Pajak Desember 2026."
        }
      ]
    },
    {
      "kind": "rule",
      "id": "REG.DTP.NO_GROSSUP",
      "label": "No employer-borne tax benefit when the government bears the tax",
      "label_id": "Tidak ada manfaat pajak ditanggung pemberi kerja ketika pajak ditanggung pemerintah",
      "valid_from": "2026-01-01",
      "valid_until": "2026-12-31",
      "recorded_on": "2025-12-31",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
          "value": "period"
        },
        {
          "name": "produces",
          "value": "tax_allowance"
        },
        {
          "name": "expression",
          "value": "0"
        },
        {
          "name": "condition",
          "value": "dtp_facility and withholding_method == 'employer_borne'"
        },
        {
          "name": "overrides",
          "value": "REG.BORNE.GROSSUP.RUNNING,REG.BORNE.GROSSUP.FINAL"
        }
      ],
      "source": [
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 5 ayat (1) dan ayat (2)",
          "page": 6,
          "quote": "Pajak Penghasilan Pasal 21 ditanggung pemerintah\nsebagaimana dimaksud dalam Pasal 2 ayat (2) merupakan\ninsentif yang harus dibayarkan secara tunai oleh Pemberi\nKerja pada saat pembayaran penghasilan kepada Pegawai\ntertentu, termasuk dalam hal Pemberi Kerja memberikan\ntunjangan Pajak Penghasilan Pasal 21 atau menanggung\nPajak Penghasilan Pasal 21 kepada Pegawai.\n(2) Pembayaran tunai Pajak Penghasilan Pasal 21 ditanggung\npemerintah sebagaimana dimaksud pada ayat (1), tidak\ndiperhitungkan sebagai penghasilan yang\ndikenakan pajak."
        },
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 2 ayat (3)",
          "page": 4,
          "quote": "Jangka waktu pemberian insentif Pajak Penghasilan\nPasal 21 ditanggung pemerintah sebagaimana dimaksud\npada ayat (2) diberikan untuk Masa Pajak Januari 2026\nsampai dengan Masa Pajak Desember 2026."
        }
      ]
    },
    {
      "kind": "rule",
      "id": "REG.DTP.REFUND",
      "label": "Refund only excess withholding not borne by the government",
      "label_id": "Pengembalian hanya atas kelebihan potong yang tidak ditanggung pemerintah",
      "valid_from": "2026-01-01",
      "valid_until": "2026-12-31",
      "recorded_on": "2025-12-31",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
          "value": "year"
        },
