        {
          "name": "condition",
          "value": "dtp_eligible"
        },
        {
          "name": "overrides",
          "value": "REG.YEAR.REFUND"
        }
      ],
      "source": [
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 5 ayat (5)",
          "page": 6,
          "quote": "Dalam hal jumlah Pajak Penghasilan Pasal 21 ditanggung\npemerintah untuk Pegawai Tetap tertentu yang telah\ndipotong dan diberikan insentif dalam tahun kalender\nyang bersangkutan lebih besar dari Pajak Penghasilan\nPasal 21 yang terutang untuk 1 (satu) Tahun Pajak,\nkelebihan Pajak Penghasilan Pasal 21 ditanggung\npemerintah tidak dikembalikan kepada Pegawai Tetap\nbersangkutan."
        },
        {
          "document": "PMK-105-2025",
          "provision": "Pasal 2 ayat (3)",
          "page": 4,
          "quote": "Jangka waktu pemberian insentif Pajak Penghasilan\nPasal 21 ditanggung pemerintah sebagaimana dimaksud\npada ayat (2) diberikan untuk Masa Pajak Januari 2026\nsampai dengan Masa Pajak Desember 2026."
        }
      ]
    },
    {
      "kind": "rule",
      "id": "REG.DTP.THP_CASH",
      "label": "Mandatory DTP cash payment under every withholding method",
      "label_id": "Pembayaran tunai DTP wajib pada setiap metode pemotongan",
