      "valid_until": "2026-12-31",
      "recorded_on": "2025-12-31",
      "fields": [
        {
          "name": "layer",
          "value": "regulation"
        },
        {
          "name": "modality",
          "value": "mandatory"
        },
        {
          "name": "scope",
